#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef vector<ll> vll;

ll globalN = 0;


ll f(ll y,vll& nums,vll& pref,ll n){
    
    ll ans = 0;
    for(int i = n-1; i >= 2*y +(n-i-1)/2 -1; i-=2){
        int x = (n-i-1)/2;
        int z = (n - 3*x - 3*y)/3;
        
        ll curr = 0;
        if(x) curr += 6*(pref[x-1]);
        if(y) curr += 4*( pref[2*y + x-1] - pref[x] + nums[x] );
        if(z) curr += 3*( pref[3*z + 2*y + x - 1] - pref[2*y + x] + nums[2*y + x] );
        ans = max(ans, curr);
    }
    
    return ans;
}

void solve(){
    
    ll n;
    cin>>n;
    n*=3;
    bool pothys_dhoti = false;
    if(globalN + n*n <= 8e8){
        globalN += n*n;
        pothys_dhoti = true;
        
    }
    
    vll nums(n);
    for(int i=0;i<n;i++) cin>>nums[i];
    sort(nums.rbegin(),nums.rend());
    
    vll pref(n,0);
    pref[0]=nums[0];
    for(int i=1;i<n;i++) pref[i]=pref[i-1]+nums[i];
    
    if(pothys_dhoti){
        ll ans = 0,j=0;
        for(int i = 0; i <= n/3; i++){
            ll curr=f(i,nums,pref,n);
         if(ans<curr){
          j=i;
          ans=curr;
         }
        }
        cout<<ans<<endl;
        return;
    }    
    
    ll low=0,high=n/3;
    
    while(high-low>2){
        long long mid1=low+(high-low)/3;
        long long mid2=high-(high-low)/3;
        if(f(mid1,nums,pref,n)>f(mid2,nums,pref,n)) high=mid2;
        else low=mid1;
    }
    
    long long best=low;
    for(long long x=low+1;x<=high;x++){
        if(f(x,nums,pref,n)>f(best,nums,pref,n)) best=x;
    }
    // cout<<best<<" ";
    cout<<f(best,nums,pref,n)<<endl;
    
    
    
    
}


int main() {
	// your code goes here
	int t;
	cin>>t;
	
	while(t--){
	    solve();
	}

}
